def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    base = counts.most_common(1)[0][0]

    # Grid lines contain no background-tile cells.
    rows = [r for r in range(h) if base not in grid[r]]
    cols = [c for c in range(w) if all(grid[r][c] != base for r in range(h))]

    # The most common non-background color is the scaffold color.
    scaffold = Counter(v for row in grid for v in row if v != base).most_common(1)[0][0]

    # Discard unused outer grid lines, if present.
    while len(rows) > 2 and all(grid[rows[0]][c] == scaffold for c in cols):
        rows.pop(0)
    while len(rows) > 2 and all(grid[rows[-1]][c] == scaffold for c in cols):
        rows.pop()
    while len(cols) > 2 and all(grid[r][cols[0]] == scaffold for r in rows):
        cols.pop(0)
    while len(cols) > 2 and all(grid[r][cols[-1]] == scaffold for r in rows):
        cols.pop()

    out = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]], grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]], grid[rows[i + 1]][cols[j + 1]]
            ]
            if corners[0] != base and corners[0] != scaffold and all(v == corners[0] for v in corners):
                out_row.append(corners[0])
            else:
                out_row.append(base)
        out.append(out_row)
    return out
